import { clerkClient, clerkMiddleware, requireAuth, getAuth } from "@clerk/clerk-sdk-node";
import type { RequestHandler } from "express";

export { clerkClient, clerkMiddleware, requireAuth, getAuth };

export const requireUser: RequestHandler = (req, res, next) => {
  const { userId } = getAuth(req);
  if (!userId) {
    res.status(401).json({ error: "Not signed in" });
    return;
  }
  next();
};

import { ClerkProvider, SignedIn, SignedOut, SignInButton, UserButton } from "@clerk/clerk-react";
import type { ReactNode } from "react";

const publishableKey = import.meta.env.VITE_CLERK_PUBLISHABLE_KEY as string;

export function ClerkProviderWrapper({ children }: { children: ReactNode }) {
  if (!publishableKey) {
    return <div className="p-4 text-sm text-red-600">Set VITE_CLERK_PUBLISHABLE_KEY to enable auth.</div>;
  }
  return <ClerkProvider publishableKey={publishableKey}>{children}</ClerkProvider>;
}

export function AuthHeader() {
  return (
    <div className="flex items-center gap-3">
      <SignedOut>
        <SignInButton mode="modal" />
      </SignedOut>
      <SignedIn>
        <UserButton afterSignOutUrl="/" />
      </SignedIn>
    </div>
  );
}
